using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using MacroStudio.Core;

namespace MacroStudio;
public sealed class ActionEditor : Window
{
    public MacroAction? Result {get;private set;}
    public ActionEditor(MacroAction source,string? baseDirectory=null,IEnumerable<string>? labels=null){
        WindowTheme.Apply(this);source=MacroStore.Clone(source);Title="Edit action";Width=640;Height=740;MinWidth=500;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;
        var root=new DockPanel{Margin=new(22)};Content=root;var footer=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var apply=new Button{Content="Apply action",IsDefault=true};footer.Children.Add(new Button{Content="Cancel",IsCancel=true});footer.Children.Add(apply);
        var panel=new StackPanel();root.Children.Add(new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
        TextBox Field(Panel parent,string name,string value,bool multiline=false){parent.Children.Add(new TextBlock{Text=name,TextWrapping=TextWrapping.Wrap});var box=new TextBox{Text=value,AcceptsReturn=multiline,MinHeight=multiline?75:0,TextWrapping=multiline?TextWrapping.Wrap:TextWrapping.NoWrap};System.Windows.Automation.AutomationProperties.SetName(box,name);parent.Children.Add(box);return box;}
        StackPanel Section(){var section=new StackPanel{Margin=new(0,8,0,0)};panel.Children.Add(section);return section;}
        void Visible(UIElement element,bool show)=>element.Visibility=show?Visibility.Visible:Visibility.Collapsed;
        panel.Children.Add(new TextBlock{Text="Action type",FontWeight=FontWeights.SemiBold});var kind=new ComboBox{ItemsSource=Enum.GetValues<ActionKind>(),SelectedItem=source.Kind};panel.Children.Add(kind);
        var enabled=new CheckBox{Content="Enabled",IsChecked=source.Enabled};panel.Children.Add(enabled);
        var delay=Field(panel,"Delay before action (ms)",source.DelayMs.ToString(System.Globalization.CultureInfo.InvariantCulture));
        var timing=Section();var duration=Field(timing,"Duration (ms)",source.DurationMs.ToString(System.Globalization.CultureInfo.InvariantCulture));
        var textPanel=Section();var text=Field(textPanel,"Unicode text (supports ${variables})",source.Text,true);
        var visual=new Button{Content="Configure visual target / capture region / wait..."};panel.Children.Add(visual);visual.Click+=(_,_)=>{source.Kind=(ActionKind)kind.SelectedItem;var d=new DetectionEditor(source,baseDirectory??Environment.CurrentDirectory){Owner=this};if(d.ShowDialog()==true)source.Detection=d.Result;};
        var data=new Button{Content="Configure variables / OCR / file data..."};panel.Children.Add(data);data.Click+=(_,_)=>{source.Kind=(ActionKind)kind.SelectedItem;var d=new DataEditor(source){Owner=this};if(d.ShowDialog()==true){source.Data=d.Result;source.Bindings=d.Bindings;}};
        var flow=new Button{Content="Configure labels / branches / repeats / calls / timeout..."};panel.Children.Add(flow);flow.Click+=(_,_)=>{source.Kind=(ActionKind)kind.SelectedItem;var d=new FlowEditor(source,labels??[]){Owner=this};if(d.ShowDialog()==true)source.Flow=d.Result;};
        var pointer=Section();pointer.Children.Add(new TextBlock{Text="Coordinate mode"});var coordinates=new ComboBox{ItemsSource=Enum.GetValues<CoordinateMode>(),SelectedItem=source.Coordinates};pointer.Children.Add(coordinates);var x=Field(pointer,"X (physical pixels; fallback position for ImageClick)",source.X.ToString());var y=Field(pointer,"Y (physical pixels; fallback position for ImageClick)",source.Y.ToString());
        var buttonPanel=Section();buttonPanel.Children.Add(new TextBlock{Text="Mouse button"});var button=new ComboBox{ItemsSource=Enum.GetValues<MacroStudio.Core.MouseButton>(),SelectedItem=source.Button};buttonPanel.Children.Add(button);var down=new CheckBox{Content="Down (unchecked = up; ImageClick sends a complete click)",IsChecked=source.IsDown};buttonPanel.Children.Add(down);
        var scrollPanel=Section();var wheel=Field(scrollPanel,"Scroll delta (120 = one notch)",source.WheelDelta.ToString());var horizontal=new CheckBox{Content="Horizontal scroll",IsChecked=source.Horizontal};scrollPanel.Children.Add(horizontal);
        var keyPanel=Section();var vk=Field(keyPanel,"Virtual key code (decimal, 65 = A)",source.VirtualKey.ToString());var scan=Field(keyPanel,"Scan code (0 = virtual key)",source.ScanCode.ToString());var extended=new CheckBox{Content="Extended key",IsChecked=source.Extended};keyPanel.Children.Add(extended);var keyDown=new CheckBox{Content="Key down (unchecked = up)",IsChecked=source.IsDown};keyPanel.Children.Add(keyDown);
        var chordPanel=Section();var keys=Field(chordPanel,"Key chord (comma-separated decimal codes, modifiers first)",string.Join(",",source.Keys));
        var pathPanel=Section();var path=Field(pathPanel,"Mouse path JSON [{x, y, offsetMs}, ...]",JsonSerializer.Serialize(source.Path,MacroStore.Json),true);
        var windowPanel=Section();var process=Field(windowPanel,"Target process name (without .exe)",source.Target?.ProcessName??"");var title=Field(windowPanel,"Window title (exact preferred)",source.Target?.Title??"");var left=Field(windowPanel,"Recorded window left",(source.Target?.Left??0).ToString());var top=Field(windowPanel,"Recorded window top",(source.Target?.Top??0).ToString());var width=Field(windowPanel,"Recorded window width",(source.Target?.Width??900).ToString());var height=Field(windowPanel,"Recorded window height",(source.Target?.Height??700).ToString());
        var comment=Field(panel,"Comment",source.Comment);
        var debug=new StackPanel();var breakpoint=new CheckBox{Content="Pause before this action (breakpoint)",IsChecked=source.Breakpoint};debug.Children.Add(breakpoint);var group=Field(debug,"Group (adjacent actions collapse together)",source.Group);panel.Children.Add(new Expander{Header="Debugging and organization",Content=debug,Margin=new(0,10,0,10)});
        var bindings=new Button{Content="Numeric property bindings..."};panel.Children.Add(bindings);bindings.Click+=(_,_)=>{var d=new DataEditor(source){Owner=this};if(d.ShowDialog()==true){source.Data=d.Result;source.Bindings=d.Bindings;}};
        var error=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=System.Windows.Media.Brushes.IndianRed};panel.Children.Add(error);
        void Update(){var k=(ActionKind)kind.SelectedItem;bool isPointer=k is ActionKind.MouseButton or ActionKind.Scroll or ActionKind.MousePath or ActionKind.WaitPixel or ActionKind.ImageClick;Visible(timing,k is ActionKind.Delay or ActionKind.MousePath);Visible(textPanel,k==ActionKind.Text);Visible(pointer,isPointer);Visible(buttonPanel,k is ActionKind.MouseButton or ActionKind.ImageClick);Visible(scrollPanel,k==ActionKind.Scroll);Visible(keyPanel,k==ActionKind.Key);Visible(chordPanel,k==ActionKind.KeyChord);Visible(pathPanel,k==ActionKind.MousePath);Visible(visual,k is >=ActionKind.ImageClick and <=ActionKind.OcrFind);Visible(data,k is >=ActionKind.Screenshot and <=ActionKind.WriteCsv or ActionKind.Branch or ActionKind.AiText or ActionKind.AiImage);Visible(flow,k is >=ActionKind.Label and <=ActionKind.CallMacro or >=ActionKind.ImageClick and <=ActionKind.WaitWindow or ActionKind.AiText or ActionKind.AiImage);Visible(windowPanel,k is ActionKind.FocusWindow or ActionKind.WaitWindow||isPointer&&(CoordinateMode)coordinates.SelectedItem==CoordinateMode.Window);}
        kind.SelectionChanged+=(_,_)=>Update();coordinates.SelectionChanged+=(_,_)=>Update();Update();
        apply.Click+=(_,_)=>{try{var a=MacroStore.Clone(source);a.Kind=(ActionKind)kind.SelectedItem;a.Enabled=enabled.IsChecked==true;a.DelayMs=double.Parse(delay.Text,System.Globalization.CultureInfo.InvariantCulture);a.DurationMs=double.Parse(duration.Text,System.Globalization.CultureInfo.InvariantCulture);a.Text=text.Text;a.Comment=comment.Text;a.Breakpoint=breakpoint.IsChecked==true;a.Group=group.Text;a.Coordinates=(CoordinateMode)coordinates.SelectedItem;a.X=int.Parse(x.Text);a.Y=int.Parse(y.Text);a.Button=(MacroStudio.Core.MouseButton)button.SelectedItem;a.IsDown=a.Kind==ActionKind.Key?keyDown.IsChecked==true:down.IsChecked==true;a.WheelDelta=int.Parse(wheel.Text);a.Horizontal=horizontal.IsChecked==true;a.VirtualKey=int.Parse(vk.Text);a.ScanCode=int.Parse(scan.Text);a.Extended=extended.IsChecked==true;a.Keys=keys.Text.Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Select(int.Parse).ToList();a.Path=JsonSerializer.Deserialize<List<PathPoint>>(path.Text,MacroStore.Json)??[];a.Target=string.IsNullOrWhiteSpace(process.Text)?null:new(process.Text.Trim(),title.Text,int.Parse(left.Text),int.Parse(top.Text),int.Parse(width.Text),int.Parse(height.Text));MacroStore.Validate(new(){Actions=[a]});Result=a;DialogResult=true;}catch(Exception ex){error.Text=ex.Message;error.BringIntoView();}};
    }
}
